#!/bin/bash
set -e

echo "Checking tools/list..."
npx @modelcontextprotocol/inspector --cli node dist/index.js --method tools/list > /tmp/tools.json
grep -q "search_notes" /tmp/tools.json || { echo "search_notes missing"; exit 1; }

echo "Calling search_notes..."
npx @modelcontextprotocol/inspector --cli node dist/index.js \
  --method tools/call --tool-name search_notes --tool-arg query=test > /tmp/call.json
grep -q "content" /tmp/call.json || { echo "no content in response"; exit 1; }

echo "Smoke test passed"
